def lexical_entries(language):
    entries, glosses = build_entries(language, PLACES | PEOPLE, SENSES, set(PLACES))
    july = quantity(7, "ordinal")["form"] + " " + language.lexicon["month"]["form"]
    entries["july_source"] = dict(form=july, roman=language.reading(july), pos="proper",
        meaning="July, the seventh month of the source calendar in Buckingham's comparison of clear springs and proof.",
        semanticId="lex.july_source", origin="Native Unta ordinal and month, following the established names of source months.",
        usageScope="later-standard", status="authored", historicalForms=[])
    glosses["july_source"] = "July"
    return entries, glosses


def prepare():
    add_source_entries("henry-viii", "henry-vi-part-3", lexical_entries,
                       "The two kings at the French meeting, the nobles who report it and the cardinal who organized it have distinct entries. Buckingham's accusation remains reported speech.")


if __name__ == "__main__":
    prepare()
